// Transparent PNG crops from the user-supplied 3.18.47.png.
const pieces = {
  br: '',
  bn: '',
  bb: '',
  bq: '',
  bk: '',
  bp: '',
  wr: '',
  wn: '',
  wb: '',
  wq: '',
  wk: '',
  wp: '',
}

export function pieceImage(type, color) {
  const image = new Image()
  image.className = 'piece ' + color
  image.alt = ''
  image.src = 'data:image/png;base64,' + pieces[color + type]
  return image
}
